// Which way a ScrollStage plays, decided from the viewport. Pure, so it is unit-tested without a browser.
export type ScrollStageMode =
  /** The stage pins and the scroll scrubs `--p` from 0 to 1. */
  | 'pinned'
  /** No pinning (narrow screens): `--p` plays 0 to 1 once when the stage comes into view. */
  | 'stacked'
  /** Reduced motion: no scroll-linked animation, `--p` stays at 1 so the finished state shows. */
  | 'static'

export function scrollStagePlan (width: number, reducedMotion: boolean, pinFrom: number): ScrollStageMode {
  if (reducedMotion) return 'static'
  if (width < pinFrom) return 'stacked'

  return 'pinned'
}

/** Coalesces a burst of requests into one `run` per frame. `schedule`/`cancel` are injected (requestAnimationFrame). */
export function createFrameThrottle (
  run: () => void,
  schedule: (callback: () => void) => number,
  cancel: (id: number) => void
) {
  let pending: number | null = null

  return {
    request () {
      if (pending !== null) return

      pending = schedule(() => {
        pending = null
        run()
      })
    },
    cancel () {
      if (pending === null) return

      cancel(pending)
      pending = null
    },
  }
}

export interface ScrollStageChapter {
  /** Progress (0..1) where the chapter starts. */
  at: number
  label: string
}

/** Index of the chapter a progress value falls in: the last one that has started (0 before the first `at`). */
export function chapterAt (progress: number, chapters: readonly ScrollStageChapter[]): number {
  let index = 0

  chapters.forEach((chapter, i) => {
    if (progress >= chapter.at) index = i
  })

  return index
}

/** The page scroll offset that puts a pinned stage at `progress`, given its trigger's start and end offsets. */
export const progressToScroll = (start: number, end: number, progress: number) =>
  start + (end - start) * Math.min(1, Math.max(0, progress))

/**
 * One frame of easing `current` toward `target`. Returns the new value and a velocity in -1..1 (how far it still has
 * to travel, so it is 0 at rest): the pair that feeds `--ps` and `--v`.
 */
export function smoothToward (current: number, target: number, ease = 0.12) {
  const gap = target - current

  if (Math.abs(gap) < 0.0005) return { value: target, velocity: 0 }

  return { value: current + gap * ease, velocity: Math.min(1, Math.max(-1, gap * 8)) }
}

// Scrolling lands a hair short of an exact value, so a chapter jump aims just past its start to count as inside it,
// but never further than halfway to the next chapter (chapters can be closer together than the nudge).
const CHAPTER_NUDGE = 0.002

/** The progress a jump to `chapter` should scroll to. */
export function chapterTarget (chapter: ScrollStageChapter, chapters: readonly ScrollStageChapter[]): number {
  const next = chapters[chapters.indexOf(chapter) + 1]?.at ?? 1

  return chapter.at + Math.min(CHAPTER_NUDGE, (next - chapter.at) / 2)
}

import type { CSSProperties } from 'react'

// Animate with CSS only. A ScrollStage writes its progress (0..1) to the `--p` custom property, and every helper
// here returns a style that is a `calc()` of it: no JS runs per frame and nothing re-renders.
// `a` and `b` are progress values. An effect holds its start state before `a` and its end state after `b`.

/** Writes the progress where the helpers (and `data-progress`) read it. */
export function writeProgress (element: HTMLElement, progress: number) {
  const value = progress.toFixed(4)

  element.dataset.progress = value
  element.style.setProperty('--p', value)
}

/** Writes the eased progress `--ps` and the signed velocity `--v` (-1..1, 0 at rest). */
export function writeSmoothed (element: HTMLElement, value: number, velocity: number) {
  element.style.setProperty('--ps', value.toFixed(4))
  element.style.setProperty('--v', velocity.toFixed(3))
}

/** 0 until `a`, 1 from `b`, linear in between (a CSS number, usable inside any calc()). */
export const seg = (a: number, b: number) => {
  // Rounded so 0.6 - 0.2 is not written as 0.39999999999999997, and never 0 so a === b cannot divide by zero.
  const span = Math.max(Number((b - a).toFixed(4)), 0.0001)

  return `clamp(0, calc((var(--p) - ${a}) / ${span}), 1)`
}

/** Draws an SVG shape in from its start. Put `pathLength={1}` on the element. */
export const draw = (a: number, b: number): CSSProperties => ({
  strokeDasharray: 1,
  strokeDashoffset: `calc(1 - ${seg(a, b)})`,
})

export const fade = (a: number, b: number): CSSProperties => ({ opacity: seg(a, b) })

/** Fades in while sliding from (dx, dy) px to its place. */
export const rise = (a: number, b: number, dx = 0, dy = 12): CSSProperties => ({
  opacity: seg(a, b),
  transform: `translate(calc((1 - ${seg(a, b)}) * ${dx}px), calc((1 - ${seg(a, b)}) * ${dy}px))`,
})

/** Moves from the origin to (dx, dy) px. */
export const travel = (a: number, b: number, dx: number, dy = 0): CSSProperties => ({
  transform: `translate(calc(${seg(a, b)} * ${dx}px), calc(${seg(a, b)} * ${dy}px))`,
})

/** Visible only between `a` and `b`, fading in and out over `edge`. */
export const pulse = (a: number, b: number, edge = 0.03): CSSProperties => ({
  opacity: `calc(min(${seg(a, a + edge)}, 1 - ${seg(b - edge, b)}))`,
})

'use client'

import { gsap } from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { useCallback, useEffect, useRef, useState, type RefObject } from 'react'

import { writeProgress, writeSmoothed } from './scroll-progress'
import { createFrameThrottle, progressToScroll, scrollStagePlan, smoothToward } from './scroll-stage-plan'

gsap.registerPlugin(ScrollTrigger)

export interface ScrollStageOptions {
  /** How long the stage stays pinned, in viewport heights. */
  distance?: number
  /** Distance from the top of the viewport where the stage pins, e.g. a sticky header's height. */
  topOffset?: number
  /** Viewport width from which the stage pins; narrower screens play once instead. */
  pinFrom?: number
  /** Seconds the one-shot play takes on narrow screens. */
  duration?: number
  /** Called with each new progress value (0..1), e.g. to drive a canvas. */
  onProgress?: (progress: number) => void
}

/**
 * Pins `ref` while the page scrolls and writes, on that element:
 * - `--p` and `data-progress`: the scroll progress, 0..1, exactly as scrolled;
 * - `--ps`: the same progress eased, so effects trail the scroll a little instead of snapping to it;
 * - `--v`: how fast it is still moving, -1..1 and 0 at rest, for skew or blur while scrolling.
 * Which way it plays (pinned, once on narrow screens, or not at all with reduced motion) follows scrollStagePlan.
 * With smooth scrolling such as Lenis, call `ScrollTrigger.update()` from its scroll event.
 * Returns `goTo(progress)`, which scrolls a pinned stage to that progress, and `pinned`, whether a pin is live.
 */
export function useScrollStage<T extends HTMLElement> (
  ref: RefObject<T | null>,
  { distance = 1.5, topOffset = 0, pinFrom = 1024, duration = 1, onProgress }: ScrollStageOptions = {}
) {
  const onProgressRef = useRef(onProgress)
  const triggerRef = useRef<ScrollTrigger | null>(null)
  // True only while a pin is live: `goTo` has nothing to scroll to on narrow screens or with reduced motion.
  const [pinned, setPinned] = useState(false)

  useEffect(() => {
    onProgressRef.current = onProgress
  })

  useEffect(() => {
    const element = ref.current

    if (!element) return

    // The eased value chases the real one on animation frames, and stops once it has arrived.
    let target = 0
    let eased = 0
    let frame: number | null = null
    let still = false

    const tick = () => {
      frame = null

      const next = smoothToward(eased, target)

      eased = next.value
      writeSmoothed(element, eased, next.velocity)

      if (next.velocity !== 0) frame = requestAnimationFrame(tick)
    }

    const report = (progress: number) => {
      writeProgress(element, progress)
      onProgressRef.current?.(progress)
      target = progress

      if (still) {
        eased = progress
        writeSmoothed(element, eased, 0)
      } else if (frame === null) {
        frame = requestAnimationFrame(tick)
      }
    }

    let hasTriggers = false
    // Lazy content changes heights after mount, so the trigger positions are measured again (once per frame).
    const throttle = createFrameThrottle(
      () => {
        if (hasTriggers) ScrollTrigger.refresh()
      },
      callback => requestAnimationFrame(callback),
      id => cancelAnimationFrame(id)
    )
    const observer = new ResizeObserver(() => throttle.request())

    observer.observe(element)

    const media = gsap.matchMedia()

    // matchMedia only runs its callback when a condition matches, so `narrow` keeps the narrow mode reachable.
    media.add(
      {
        wide: `(min-width: ${pinFrom}px)`,
        narrow: `(width < ${pinFrom}px)`,
        reduce: '(prefers-reduced-motion: reduce)',
      },
      context => {
        const reduce = context.conditions?.reduce === true
        const width = context.conditions?.narrow === true ? pinFrom - 1 : pinFrom
        const mode = scrollStagePlan(width, reduce, pinFrom)

        hasTriggers = mode !== 'static'
        // Reduced motion shows the finished state with nothing trailing behind it.
        still = reduce

        if (mode === 'static') {
          report(1)

          return
        }

        report(0)

        if (mode === 'pinned') {
          const trigger = ScrollTrigger.create({
            trigger: element,
            start: `top ${topOffset}px`,
            end: `+=${distance * 100}%`,
            pin: true,
            // GSAP turns spacing off when the parent is a flex or grid container, which lets the next content slide under the stage.
            pinSpacing: true,
            scrub: true,
            onUpdate: self => report(self.progress),
          })

          triggerRef.current = trigger

          setPinned(true)

          // GSAP runs this when the pin is reverted (a resize across `pinFrom`, a reduced-motion change, unmount).
          return () => {
            triggerRef.current = null
            setPinned(false)
          }
        }

        const state = { value: 0 }

        ScrollTrigger.create({
          trigger: element,
          start: 'top 80%',
          once: true,
          onEnter: () => {
            gsap.to(state, { value: 1, duration, ease: 'power2.out', onUpdate: () => report(state.value) })
          },
        })
      }
    )

    return () => {
      triggerRef.current = null
      if (frame !== null) cancelAnimationFrame(frame)
      observer.disconnect()
      throttle.cancel()
      media.revert()
    }
  }, [ref, distance, topOffset, pinFrom, duration])

  /** Scrolls a pinned stage to `progress` (0..1). Does nothing when the stage is not pinned. */
  const goTo = useCallback((progress: number) => {
    const trigger = triggerRef.current

    if (!trigger) return

    window.scrollTo({ top: progressToScroll(trigger.start, trigger.end, progress), behavior: 'smooth' })
  }, [])

  return { goTo, pinned }
}

import type { ScrollStageChapter } from './scroll-stage-plan'

interface ScrollStageRailProps {
  chapters: readonly ScrollStageChapter[]
  active: number
  /** False when the stage is not pinned (narrow screens, reduced motion): the strip then only shows where you are. */
  interactive: boolean
  onSelect: (chapter: ScrollStageChapter) => void
}

/**
 * The chapter strip under a stage, in the spec-sheet voice: a hairline that fills with `--p`, then one numbered cell per
 * chapter. The active chapter is inverted; while the stage is pinned a cell scrolls it to where its chapter starts.
 */
export function ScrollStageRail ({ chapters, active, interactive, onSelect }: ScrollStageRailProps) {
  return (
    <nav aria-label='Chapters' className='border-t font-mono text-[10px] uppercase tracking-wide'>
      <div aria-hidden='true' className='h-px w-full bg-border'>
        <div className='h-px bg-foreground' style={{ width: 'calc(var(--p) * 100%)' }} />
      </div>
      <ol className='flex'>
        {chapters.map((chapter, index) => (
          <li key={chapter.label} className='min-w-0 flex-1 border-r last:border-r-0'>
            <button
              type='button'
              aria-current={index === active ? 'step' : undefined}
              disabled={!interactive}
              onClick={() => onSelect(chapter)}
              className='flex w-full items-baseline gap-2 truncate px-3 py-2 text-left transition-colors enabled:hover:bg-muted disabled:cursor-default aria-[current=step]:bg-foreground aria-[current=step]:text-background'
            >
              <span className='tabular-nums opacity-60'>{String(index + 1).padStart(2, '0')}</span>
              <span className='truncate'>{chapter.label}</span>
            </button>
          </li>
        ))}
      </ol>
    </nav>
  )
}

'use client'

import { useCallback, useRef, useState, type ComponentPropsWithoutRef, type CSSProperties } from 'react'

import { ScrollStageRail } from './scroll-stage-rail'
import { chapterAt, chapterTarget, type ScrollStageChapter } from './scroll-stage-plan'
import { useScrollStage, type ScrollStageOptions } from './use-scroll-stage'

export type { ScrollStageOptions } from './use-scroll-stage'
export type { ScrollStageChapter } from './scroll-stage-plan'
export { draw, fade, pulse, rise, seg, travel } from './scroll-progress'

type ScrollStageProps = ComponentPropsWithoutRef<'div'> & ScrollStageOptions & {
  /** Named parts of the scroll. Adds a numbered strip under the content; a cell scrolls the stage to its chapter. */
  chapters?: readonly ScrollStageChapter[]
}

/**
 * A block that pins while the page scrolls and exposes the scroll progress as CSS variables:
 * `--p` (0..1), `--ps` (the same, eased) and `--v` (velocity, -1..1). With `chapters` it also sets `data-chapter`
 * (the active index) and shows a chapter strip.
 * Style children with the helpers from `scroll-progress` (draw, fade, rise, travel, pulse) or any `calc(var(--p))`.
 * Before scripts run `--p` is 0 (the stage starts empty); with reduced motion it is 1 (the finished state).
 */
export function ScrollStage ({ distance, topOffset, pinFrom, duration, onProgress, chapters, style, children, ...rest }: ScrollStageProps) {
  const ref = useRef<HTMLDivElement>(null)
  const [chapter, setChapter] = useState(0)

  const handleProgress = useCallback((progress: number) => {
    if (chapters) setChapter(chapterAt(progress, chapters))
    onProgress?.(progress)
  }, [chapters, onProgress])

  const { goTo, pinned } = useScrollStage(ref, { distance, topOffset, pinFrom, duration, onProgress: handleProgress })

  return (
    <div
      ref={ref}
      data-chapter={chapters ? chapter : undefined}
      style={{ '--p': 0, '--ps': 0, '--v': 0, ...style } as CSSProperties}
      {...rest}
    >
      {children}
      {chapters && chapters.length > 0 && (
        <ScrollStageRail chapters={chapters} active={chapter} interactive={pinned} onSelect={target => goTo(chapterTarget(target, chapters))} />
      )}
    </div>
  )
}

export default ScrollStage
